    body: "プログラム学習とは、アメリカの行動主義心理学者B・F・スキナーが、自らのオペラント条件づけの理論を教育の現場に応用して考案した学習方式です。娘の授業参観で、教師が延々と説明を続け、児童がただ受け身に座って聞いているだけの授業のあり方に強い疑問を抱いたことが、開発のきっかけになったと伝えられています。\n\nプログラム学習では、学習内容をごく細かいステップに分割し、一問ずつ解答させながら段階的に理解を積み上げていきます。スキナーは「ティーチングマシン」と呼ばれる装置を開発し、学習者が問題に解答すると、ただちに正誤がフィードバックされ、正答すれば次の課題へと自動的に進める仕組みを実現しました。誤答が続く場合には前の段階へ戻れるように設計されており、理解の早い学習者も遅い学習者も、それぞれ自分に合ったペースで学習を進められるようになっています。\n\nスモールステップの原理、積極的反応の原理、即時フィードバックの原理、自己ペースの原理などが柱とされ、正しい反応を積み重ねさせることで学習を強化していく考え方は、後のコンピュータ支援教育（CAI）や、ドリル型のeラーニング教材の設計にも大きな影響を与え続けています。",
