    body: "有意味受容学習とは、アメリカの教育心理学者デイヴィッド・オーズベルが提唱した学習理論です。学習内容のすべてを学習者自身に発見させる発見学習には、限られた授業時間の中で扱える内容量に限界があるとし、教師が体系立てて説明する「受容学習」であっても、学習者が既に持っている知識構造と新しい情報を意味づけながら関連づけて取り入れれば、単なる丸暗記に頼らない深く有意味な学習が十分に成立すると考えました。\n\nそのための代表的な手立てとして、学習の冒頭に提示する抽象度の高い概念的な導入である「先行オーガナイザー」を考案しました。先行オーガナイザーは、これから学ぶ内容全体の見通しを学習者に与えるとともに、学習者が既に持っている知識と新しく学ぶ知識とを橋渡しする役割を果たすとされ、授業の導入部分に位置づけて用いられます。\n\n知識を一方的に注入するのではなく、あくまで学習者自身の認知構造との関連づけを重視する点で、後の有意味学習・概念地図（コンセプトマップ）の研究や、教科書・教材における導入部分の設計にも大きな影響を及ぼしてきました。",
