    body: "ティーム・ティーチング（TT）とは、二人以上の教師がチームを組み、同じ児童生徒の集団に対して協力しながら授業の計画・実施・評価に責任を持つ授業組織の形態です。アメリカの教育学者ジュドソン・シャプリンらによって1950年代後半に理論化され、教育内容の高度化や教育方法の多様化に対応する新しい試みとして、各地の小・中学校に広がっていきました。\n\n日本には最初の実施から数年ほどで紹介され、学級担任制を基盤とする日本の学校文化の中で、教科指導の専門性を補う補助的な方法として独自の形で定着していきました。主となる教師（メインティーチャー）が学級全体への説明や発問を行い、もう一方の教師（サブティーチャー）が机間指導や個別の支援にあたるという役割分担が、日本の実践ではよく用いられます。\n\n一人の教師だけでは目が届きにくい多様な学習者のつまずきに対応しやすいという利点があり、算数・数学の少人数指導や特別支援教育における個への配慮、外国語活動における外国語指導助手（ALT）との協働授業など、幅広い場面で今日も活用され続けています。",
