      "子どもの生活経験や興味・関心を出発点に、ひとまとまりの学習活動である単元を通して教科横断的・総合的に学ばせる学習方法。デューイの経験主義に連なり、戦後の新教育で特に重視された。",
    body: "単元学習とは、教科の系統的な知識をあらかじめ細かく分割して教え込むのではなく、子どもの生活経験や関心のあるテーマを学習の出発点に据え、一定のまとまりである「単元」を通して総合的・活動的に学びを組織していく学習方法です。アメリカの教育学者ジョン・デューイに代表される経験主義教育の考え方を、理論的な背景の一つとしています。\n\n日本では第二次世界大戦後、軍国主義教育に対する反省から、子ども中心の民主主義的な人間形成をめざす新教育の中心的な考え方として広く受け入れられ、「生活単元学習」と呼ばれる、子どもの日常生活上の身近な問題解決を軸に据えた教科横断的な学習実践が、全国各地の学校で盛んに行われました。\n\nその一方で、経験を重視するあまり基礎的な知識・技能の定着が不十分になるという批判も次第に強まり、1950年代後半以降は教科の系統性を重視する系統学習が改めて強調されるようになりました。経験主義と系統主義との対比は、現在の総合的な学習の時間や教科横断的なカリキュラムのあり方を考えるうえでも、重要な論点であり続けています。",
