    body: "バズ学習（バズセッション）とは、大人数の学習集団をいくつかの小グループに分割し、それぞれのグループで短時間の討議を行わせたうえで、その結果を全体に向けて共有する討議技法です。アメリカのヒルズデール大学の学長であったJ・ドナルド・フィリップスが提唱したことで知られ、6人のグループで6分間話し合うという原則にちなんで「フィリップス66法」とも呼ばれています。\n\n各グループが同時にがやがやと活発に話し合う様子が、ハチの飛び交う羽音（buzz）に似ていることから「バズ」という名前が付けられました。人数の多い一斉授業の場面であっても、小グループに分けることで一人あたりの発言の機会が均等に確保され、大勢の前では発言しにくい学習者であっても、比較的自由に、そして積極的に議論へ参加しやすくなるという利点があります。\n\n短時間で多くの意見を効率よく引き出せることから、授業の導入場面や振り返りの場面、教員研修や会議のアイスブレイクなど、学校教育の枠にとどまらず幅広い場面で活用されている、歴史のある討議形式の一つです。",
