    body: "ブレインストーミングとは、アメリカの広告会社の経営者アレックス・F・オズボーンが考案した、集団によるアイデア発想の手法です。1941年頃、会議の進め方を見直す中で着想を得たとされ、1953年に刊行された著書『Applied Imagination』の中で、この会議方式の名称として体系的に紹介されました。日本では「ブレスト」と略して呼ばれることも多くあります。\n\n実施にあたっては、他者の意見を否定したり批判したりしない「判断保留（批判厳禁）」、既存の枠にとらわれない自由な発想を歓迎する「自由奔放」、質にこだわらずとにかく多くの意見を出す「大量発言（質より量）」、他者の意見に便乗したり複数の意見を組み合わせたりして発展させる「結合改善」という4つの原則を全員で守ることが重視されます。\n\n教育現場では、探究学習における課題設定の場面や、話し合い活動の導入、発想を広げるための授業の導入活動などに幅広く取り入れられており、批判を恐れず自由に発言できる場をつくることで、多様な意見を引き出し、児童生徒の創造的な思考を育む手法として活用されています。",
