    body: "ロールプレイ（役割演技）とは、特定の場面や人物の役割をあらかじめ割り当てられた学習者が、その立場になりきって即興的に演じることで、他者の視点や感情を疑似的に体験し、理解を深めていく学習技法です。精神科医ヤコブ・モレノが1920年代に創始した集団心理療法である「心理劇（サイコドラマ）」の考え方をその起源とし、その後、教育や医療、企業研修など非常に幅広い分野へと応用されるようになりました。\n\n学校の授業では、道徳科で提示された場面設定をもとにした話し合いや、外国語科における実践的な会話練習、キャリア教育における職場体験の前段階として行われる模擬演習など、さまざまな教科・領域で取り入れられています。演じることそのもので終わりにするのではなく、演じ終えた後に感じたことや気づいたことを互いに共有する振り返りの時間を丁寧に設けることで、学びが一層深まるとされています。\n\n実際に体を動かし、言葉を発するという行動を通じて学ぶため、知識として頭で理解するだけでは得にくい共感的な理解や、実践的な対応力を効果的に育てられる点が、この技法の大きな特徴です。",
