    body: "体験学習（経験学習）とは、人は具体的な体験そのものから直接学ぶのではなく、その体験を丁寧に振り返って意味づけ、そこから得た教訓を次の行動に活かしていくという一連の過程を通じて学ぶ、という考え方に基づく学習方法です。アメリカの組織行動学者デイヴィッド・コルブが1984年の著書『Experiential Learning』の中で示した「経験学習サイクル」が、この考え方を代表するモデルとして広く知られています。\n\nこのサイクルは、具体的経験（実際にやってみること）、内省的観察（何が起きたのかを多角的に振り返ること）、抽象的概念化（振り返りから法則や教訓を引き出し一般化すること）、能動的実験（得られた教訓を新しい状況で実際に試してみること）という4つの段階を、循環的にたどっていくものとして示されています。\n\n学校教育においては、野外活動や職場体験、実験・実習、探究的な学習活動などを行った直後に、体験した内容をあらためて言語化して丁寧に振り返る時間をしっかりと確保することが、学びをより深いものにするうえで特に重視されています。",
