    body: "ペア学習とは、学級の児童生徒を二人一組に分け、その組を単位として話し合いや教え合い、答え合わせなどの学習活動を行わせる学習方法です。四人程度の班で行うグループ学習などに比べて人数の少ない、最も基礎的で身近な形の協同学習として位置づけられ、特別な準備がなくても取り入れやすい形態でもあります。\n\n教師一人が話す一斉授業では、限られた時間の中で発言できる人数がどうしても少なくなりますが、ペア学習を取り入れることで、一時間の授業の中で学級の全員が自分の考えを声に出して説明したり、相手の意見を聞いたりする機会を確保できます。まず一人で考え、次にペアで話し合い、最後に学級全体で共有するという「シンク・ペア・シェア」と呼ばれる指導法もよく組み合わせて用いられ、自分の考えを整理してから発表する練習にもつながります。\n\n準備の手間が少なく導入しやすいうえ、大勢の前で話すことへの抵抗感が比較的少ない形態であることから、協同学習やアクティブ・ラーニングへの入り口として、学年や教科を問わず日本の学校で広く実践されています。",
