    body: "一斉指導（一斉授業）とは、一人の教師が学級全体の児童生徒に対して、同じ学習内容を同じ進度で教えていく、日本の学校で最も長く一般的に行われてきた授業形態です。児童生徒の机を黒板のほうへ向けて配置し、教師が教室の前に立って発問・説明・指示を組み合わせながら授業を進め、学級全体を一つのまとまった学習集団として導いていきます。\n\n限られた授業時間の中で共通の知識・技能を効率よく伝えられること、学級としての一体感や、互いに考えを聞き合い学び合う雰囲気をつくりやすいことなど、多くの利点がある一方で、学習の進度や理解度に一人ひとり個人差がある中で、きめ細かな個別の指導を行うことが難しいという課題も、これまで繰り返し指摘されてきました。\n\nこのため近年では、一斉指導を授業の基本的な骨組みとしながらも、机間指導やペア学習・グループ学習を効果的に組み合わせたり、個別最適な学びの考え方を取り入れたりすることで、一斉指導の長所を生かしながら、一人ひとりへの配慮を補っていく授業づくりが求められています。",
