    body: "ラウンドロビンとは、小グループの中で一人ひとりが順番に自分の意見を述べたり、一枚の用紙に自分の考えを書き加えていったりする話し合いの技法です。「持ち回り」を意味する英語に由来しており、アメリカの心理学者スペンサー・ケーガンが体系化した協同学習の構造（ストラクチャー）の一つとして、教育現場で広く知られ実践されています。\n\n二人一組で行う「シンク・ペア・シェア」とは異なり、3人以上のグループの中で順番に発言の機会を回していくため、より多様な意見や視点に触れることができます。あらかじめ発言の順番が決まっているため、特定のメンバーだけが話し続けてしまったり、逆に一言も発言しないまま話し合いが終わってしまったりすることを防ぎやすく、グループ内で参加の機会を均等に確保しやすいという特長があります。\n\nケーガンは協同学習を支える基本原理として、互恵的な相互依存・個人の責任・参加の平等性・活動の同時性という4つの原理を挙げており、ラウンドロビンはこれらの原理、とりわけ参加の平等性を具体的に実現する手立ての一つとして、授業のさまざまな場面で活用されています。",
