    body: "スパイラル・カリキュラムは、教育心理学者ブルーナーが著書『教育の過程』の中で提唱した考え方で、教科の中核となる概念や原理を、学習者の発達段階に応じた形式に翻訳しながら、学年が上がるごとに繰り返し取り上げて構成するカリキュラムです。\n\n低学年では直感的・具体的な活動を通して概念に触れさせ、学年が進むにつれて同じ概念をより抽象的・体系的な形で再び学ばせることで、螺旋階段を上るように理解を深めていきます。単元の一度きりの指導で終わらせず、系統的に繰り返す点が特徴です。\n\n算数・数学や理科の系統学習をはじめ、現行の学習指導要領における学年間の系統性を意識した内容配列の考え方の理論的基盤の一つとなっており、既習事項を生かした学び直しの単元設計にも通じています。",
