    body: "ソクラテス・メソッド(Socratic method)とは、教師が答えを一方的に教えるのではなく、体系的に構成された問い(ソクラテス的問答法)を通じて学習者自身に前提を吟味させ、矛盾に気づかせながら、より深い理解や批判的思考に到達させる指導法である。教師はあえて「無知を装う」姿勢をとり、学習者の思考を刺激する役割に徹する点に特徴がある。\n\nこの方法では、教師は単一の正解を提示するのではなく、「なぜそう考えるのか」「その根拠は何か」「別の見方はできないか」といった開かれた質問を連続的に投げかける。これにより学習者は自らの知識や信念を検証し、論理の飛躍や矛盾を自覚する過程を経て、より妥当な結論へと到達する。目的は「何を考えるか」ではなく「どう考えるか」を育てることにあり、批判的思考力や多角的視点の獲得に資するとされる。\n\n現代の教育現場では、ロースクールのケースメソッドや高等教育のゼミナール、中等教育における討論授業などで応用されており、発問を中心とした授業づくり(発問技法)や探究学習とも親和性が高い。一方で、効果的に機能させるには教師に高度な発問構成力とファシリテーション能力が求められ、準備不足だと単なる一問一答に陥る危険性も指摘されている。",
    relatedSlugs: ["hatsumon", "case-method", "tankyu-gakushu", "critical-pedagogy"],
    isCanonical: true,
    tags: ["問答法", "批判的思考", "発問", "対話型学習"],
