    body: "マイクロティーチング(microteaching)は、1960年代初頭にスタンフォード大学のドワイト・アレン(Dwight W. Allen)らによって開発された教員養成・教員研修の技法である。通常5〜20分程度の短い模擬授業を5〜10人程度の少人数(同僚教師や実習生仲間)を相手に行い、特定の教授スキル(発問、板書、説明、机間指導など)を単純化・焦点化して練習する点が特徴である。\n\n基本的な手続きは、①短い授業計画を立てる、②実際に模擬授業を行う、③録画やピアからの即時フィードバックを受ける、④フィードバックをもとに授業を修正する、⑤再度同じ内容を教え直す、という「計画―実施―フィードバック―再計画―再実施」のサイクルを繰り返す形をとる。この反復により、複雑な授業実践を構成要素に分解し、低リスクの環境で段階的に技能を向上させることができる。\n\nマイクロティーチングは教職課程における教育実習前の準備や、現職教員の授業改善研修、大学の教育開発(ファカルティ・ディベロップメント)などで広く用いられている。日本の教員養成課程でも模擬授業として類似の実践が行われており、授業研究(レッスンスタディ)と組み合わせて活用されることも多い。",
