    body: "相互教授法(reciprocal teaching)は、1984年にアン・パリンサー(Annemarie Palincsar)とアン・ブラウン(Ann L. Brown)によって開発された読解力向上のための協同的な指導法である。小集団の中で児童生徒が順番に「教師役」となり、教師がモデルとして示した読解方略を用いて対話をリードしながら文章の理解を深めていく点が特徴である。\n\n中核となるのは「予測する(predicting)」「質問する(questioning)」「明確化する(clarifying)」「要約する(summarizing)」という4つの読解方略である。教師ははじめに各方略を明示的に指導・モデル化し、その後徐々に責任を学習者に委譲していく(足場かけの漸次的解除)。この過程で学習者は自らの理解をモニタリングするメタ認知的な力を育むとともに、仲間との対話を通じて認知的・情意的な学びを深める。\n\n相互教授法は特に読解につまずきのある児童生徒に効果があるとされ、欧米では国語科・リテラシー教育の代表的な指導法として広く実践研究が蓄積されている。日本でも国語科の読解指導やアクティブラーニング型授業の一手法として紹介されることが増えており、ジグソー法や協同学習と組み合わせて実施される場合もある。",
