    body: "ジャストインタイム・ティーチング(Just-in-Time Teaching, JiTT)は、1990年代後半にグレゴール・ノバック(Gregor Novak)らによって物理教育の分野で提唱された指導方略で、授業外の予習課題と授業内活動とを緊密に結びつける点が特徴である。学習者は授業前に、まだ扱っていない内容を含む短い設問にウェブフォームなどで解答し、教師は授業直前にその回答を確認して、当日の授業の重点や進め方を調整する。\n\nこの仕組みにより、教師は学習者がどこでつまずいているか、どのような誤解を持っているかを授業前に把握でき、それに基づいて発問や説明、グループ活動の内容を柔軟に組み替えることができる。学習者にとっては、授業前に一度自分の理解を試すことで予習への動機づけが高まり、授業に主体的に臨む姿勢が養われる。反転授業の一種、あるいは「部分的な反転授業」とも位置づけられる。",
