    categories: ["methods"],
    summary:
      "1986年にドナ・オーグルが考案した読解指導のための3欄シートで、「知っていること(K)」「知りたいこと(W)」「学んだこと(L)」を学習の前後で書き出させる。",
    body: "KWL表(KWL chart / KWL table)は、1986年に教育学者ドナ・オーグル(Donna Ogle)が提唱した読解・学習支援のための視覚的なツールである。K(Know:すでに知っていること)、W(Want to know:知りたいこと)、L(Learned:学んだこと)の3つの欄からなる表を用いて、読解や単元学習の前・中・後の各段階で学習者の思考を整理させる点に特徴がある。\n\n授業や読解活動の前に、まず学習者はトピックについてすでに知っていることをKの欄に書き出し、既有知識を活性化する。次に、学びたいこと・疑問に思うことをWの欄に記入し、学習の見通しと目的意識を持たせる。学習活動やテキストの読解が終わった後には、実際に学んだことをLの欄にまとめ、当初の疑問がどう解消されたかを振り返る。\n\nこの一連の手続きは、既有知識と新しい情報を結びつける構成主義的な学習観に基づいており、読解力育成だけでなく理科・社会科などの単元導入時における動機づけや学習の見通しづくりにも広く用いられている。グラフィックオーガナイザーの一種として、他の視覚化ツールと組み合わせて活用されることも多い。",
