    summary:
      "情報同士の関係を図形や線でつなぎ視覚的に表す学習支援ツールの総称。ベン図・概念地図・フローチャートなどが含まれ、思考の整理や記憶の定着を助ける。",
    body: "グラフィックオーガナイザー(graphic organizer)は、情報や概念どうしの関係性を図形・線・矢印などを用いて視覚的に表現する学習ツールの総称である。ブレインストーミングによる発想の整理、比較・対照、分類、時系列の整理、文章構成の計画など、思考の種類に応じてさまざまな型が使い分けられる。\n\n代表的な種類として、共通点と相違点を示すベン図(Venn diagram)、中心概念から関連事項を放射状に広げるマインドマップ、手順や因果関係を示すフローチャート、特徴を整理する記述的特徴表(feature chart)、階層関係を示すツリー図などがある。これらは新しい情報を短期記憶から長期記憶へ移行させる際の足場となり、抽象的な概念を具体的・視覚的な形に変換する働きを持つ。\n\n国語・理科・社会など教科を問わず、読解指導、概念形成、レポートや論述の構想段階など幅広い場面で活用されている。概念地図(コンセプトマップ)やKWL表はグラフィックオーガナイザーの代表的な具体例と位置づけられ、ICTを活用したデジタルツールとの組み合わせでも普及が進んでいる。",
