    reading: "ふぃっしゅぼうるでぃすかっしょん",
    kana: "ふ",
    categories: ["methods"],
    summary:
      "少人数の内側の輪(インナーサークル)が討議を行い、外側の学習者はそれを観察・記録するという二重の円構造を用いる討論技法。全員参加と発言の質の両立をねらう。",
    body: "フィッシュボウル・ディスカッション(fishbowl discussion)は、学級を内側と外側の二重の円(サークル)に分けて行う討論技法である。内側の輪(インナーサークル、一般に6〜12人程度)に座った学習者が中心となって議論を行い、外側の輪の学習者はその様子を観察し、議論の内容や進め方についてメモを取りながら思考を深める。金魚鉢(fishbowl)の中を外から観察する様子になぞらえてこの名がついている。\n\nこの技法は、全員が一度に発言することが難しい大人数の学級において、少人数での深い議論と全体での学びを両立させることができる点に利点がある。発言に消極的な学習者も、まず外側から議論のモデルを観察することで、良い討論の進め方(根拠の示し方、他者の意見への応答の仕方など)を学ぶことができる。実施形態によっては、外側の学習者が空いている椅子に座って一時的に議論に加わる方式や、途中で内側と外側を入れ替える方式も用いられる。\n\n議論が対立を含む論争的なテーマや、多様な視点の共有が求められる社会科・道徳科の授業などで特に効果的とされ、ディベートやワールドカフェと並ぶ協同的な話し合い活動の一技法として位置づけられる。",
