    body: "プロジェクト・アプローチ(project approach)は、教育学者リリアン・カッツ(Lilian Katz)とシルビア・チャード(Sylvia Chard)が体系化した幼児教育・初等教育向けの指導法で、子どもや教師が関心を持ったテーマを、数日から数週間にわたり深く掘り下げて調べる「プロジェクト」を学習活動の中心に据える点が特徴である。プロジェクトとは、子どもの興味に基づき、教育的価値があると教師が判断したテーマについての継続的な調査活動と定義される。\n\nプロジェクトは一般に「導入(トピックの選定と既有知識の共有)」「探究(フィールドワークや調査、専門家への質問など)」「まとめ(成果の発表や振り返り)」という段階を経て進められる。教師が問いを一方的に与えるのではなく、子ども自身の疑問や関心から探究のテーマが立ち上がり、その過程で観察・記録・表現・協働といった多様な力が育まれる点が重視される。\n\nこの方法はレッジョ・エミリア・アプローチとも親和性が高く、また学齢期以降のプロジェクト型学習(PBL)の源流の一つとも位置づけられる。日本の幼児教育・保育においても、子どもの主体的な興味関心を出発点とする保育実践として紹介されることが増えている。",
