    body: "責任の漸次的移行モデル(Gradual Release of Responsibility, GRR)は、1983年に米国の研究者P・デイビッド・ピアソン(P. David Pearson)とマーガレット・ギャラガー(Margaret Gallagher)によって提唱された指導モデルであり、学習課題の遂行に関する責任を、教師から学習者へと段階的に移していくプロセスとして授業を設計する枠組みである。\n\n原型となる3段階は「I do(教師によるモデル提示)」「We do(教師と学習者による協働的な練習)」「You do(学習者による自立的な取り組み)」から構成される。「I do」では教師が思考過程を声に出しながら手本を示し、「We do」では教師の支援のもとで学習者が練習を積み、「You do」では学習者が自力で課題に取り組む。この後、教育学者ナンシー・フレイ(Nancy Frey)とダグラス・フィッシャー(Douglas Fisher)によって、学習者同士が協働して取り組む段階(You do it together)を加えた4段階モデルへと発展した。\n\nこのモデルは、教師による直接的な指導とスキャフォールディング(足場かけ)、そして学習者の自己調整学習への移行を一つの連続体として捉える点に特徴があり、国語科の読解指導をはじめ、新しい技能や概念を導入するあらゆる授業場面で活用される基本的な指導設計の考え方として広く参照されている。",
    relatedSlugs: ["scaffolding", "chokusetsu-kyoju", "self-regulated-learning"],
    isCanonical: true,
    tags: ["足場かけ", "授業デザイン", "自立的学習", "指導の段階化"],
