    body: "水道方式は、数学者・遠山啓（1909〜1979）と銀林浩を中心とする民間教育団体・数学教育協議会（数教協）が、1958年頃に創始したとされる算数の計算指導の体系です。狭義には、小学校の筆算の問題を、繰り上がり・繰り下がりの有無や0を含むかどうかで分類し、最も一般的なタイプから0を含むような特殊なタイプへと配列して指導する方法を指します。体系をまとめた『水道方式による計算体系』は1960年に刊行され、1960年代の教育現代化運動を代表する実践として広く知られるようになりました。\n\n位取りの理解を支える教具として、正方形の「タイル」を用いる点も特徴です。1を小さな正方形、10個をまとめた「十の棒」、さらにその10本を束ねた「百の板」で表すことで、十進位取り記数法の仕組みを視覚的・操作的に理解させます。遠山は、計算技能は手早く身につけさせ、余った時間をより重要な教材に充てるべきだと考えており、その重要教材の系統として示したのが「量の体系」でした。\n\n水道方式は、教育課程の自主編成運動の象徴として肯定的に評価される一方、数学教育の研究者・実践者の間では評価が分かれることも指摘されています。それでも、「どの型から教えれば子どもがつまずきにくいか」を計算の構造から系統的に考える発想は、教材研究と指導系列のあり方を考える上で今日も参照されています。",
