    body: "仮説実験授業は、科学史家・教育学者の板倉聖宣が1960年代に提唱した授業の理論と方法です。核心は、「問題→予想→討論→実験」という過程を積み重ね、科学的な概念や法則を学ぶことにあります。まず教師が問題を出し、子どもたちは選択肢の中から自分の予想を選んで理由を述べ合い、意見を交わしたあとで実験を行って結果を確かめます。「すべての認識は実験によってのみ成立する」という認識論に立ち、予想を立てて検証する経験そのものを学習の中心に置いています。\n\nこの授業は、《授業書》と呼ばれる教材に沿って進められます。授業書は教科書・ノート・読み物としての性格を併せ持ち、教師用の手引きも含む統合的な教材です。多くの実験授業を重ねて、誰が行っても同じような成果が再現されることを確かめながら練り上げられる点が特徴で、《力と運動》などが代表的な授業書として知られます。理論の原典とされる「科学的認識の成立過程」「仮説実験授業とは何か」は、1966年に雑誌『理科教室』に発表されました。\n\n教師の力量や経験に頼りがちな授業を、教材と授業運営の手順によって再現可能にしようとした点で、この方式は教育方法史上の独自の試みといえます。のちに仮説社の月刊誌『たのしい授業』（1983年創刊）などを通じて「たのしい授業」の運動へと広がり、理科にとどまらず社会や算数の授業書も作られました。",
