    slug: "audiolingual-method",
    title: "オーディオ・リンガル法",
    reading: "おーでぃお・りんがるほう",
    kana: "お",
    categories: ["methods"],
    summary:
      "構造言語学と行動主義心理学に基づき、文型練習（パターン・プラクティス）の反復で言語習慣を形成させる外国語教授法。",
    body: "オーディオ・リンガル法は、1950〜60年代のアメリカで発展した外国語教授法です。理論的な基盤は、アメリカ先住民の言語を研究した構造言語学と、刺激と反応の条件づけによって習慣が形成されると考える行動主義心理学にあります。第二次世界大戦中に軍人へ外国語を短期間で教える必要があったことが、その発展の背景として挙げられています。\n\n中心となる技法は、ラドー（R. Lado）やフリーズ（C. Fries）らによって整えられた文型練習（パターン・プラクティス）です。教師の示す文型を模倣・反復し、語句を入れ替える代入練習や文を変形する練習を繰り返すことで、正しい言語習慣を自動化させます。聞く・話すを重視し、文字は後から導入する点、明示的な文法説明を避ける点、誤りをできるだけ出させない点などが、文法の説明と訳読を中心とする伝統的な文法訳読法と対照的です。\n\nその後、言語は習慣ではなく規則に基づく創造的な営みであるとする立場や認知学習理論から、意味を伴わない機械的反復になりがちで、実際の場面での運用に結びつきにくいと批判されました。この批判はコミュニカティブ・アプローチの台頭を促しましたが、ドリルによる基本文型の定着という発想は、現在も日本の外国語授業の練習活動に息づいています。",
