    summary:
      "ジャック=ダルクローズが創始した音楽教育法。リズム運動・ソルフェージュ・即興の3つを柱に、身体の動きを通して音楽性を育てる。",
    body: "ダルクローズ・リトミックは、スイスの音楽教育者エミール・ジャック=ダルクローズ（1865〜1950）が創始した音楽教育法です。ジュネーヴ音楽院でソルフェージュと和声学を教えていた彼は、演奏技術に偏った当時の音楽教育に疑問を抱き、音楽の根幹であるリズムを身体の動きを通して体得させる方法を考案し、Eurhythmics（ユーリズミックス）と名づけました。\n\n学習の柱は、リズム運動（リトミックそのもの）、ソルフェージュ（聴音・視唱）、即興演奏の3つに体系づけられています。たとえば、ピアノの音の強弱や速さに合わせて歩く、止まる、拍を打つといった活動で、聴く力、反応する力、集中力、表現力を養います。音楽の動きと身体の動きを一致させる考え方は、のちのモダンダンスや身体表現教育にも影響を与えました。\n\n現在では音楽教育にとどまらず、音楽療法、演劇教育、舞踊、幼児教育などに広く応用されています。日本では幼児や子ども向けの音楽教室で普及しましたが、リズム遊びの名称として「リトミック」が使われるうちに、本来の教育理念とは異なる形で用いられることへの懸念が、ダルクローズ関係者から示されている点にも注意が必要です。",
    relatedSlugs: ["kodaly-method", "experiential-learning", "montessori", "shocho-asobi"],
