    summary:
      "パーカーストが提唱した個別学習の方式。教科ごとの月間課題（アサイメント）を、生徒が自分の計画で進める。",
    body: "ドルトン・プランは、アメリカの教育者ヘレン・パーカースト（H. Parkhurst）が1919〜1920年頃に考案した個別学習の方式です。マサチューセッツ州ドルトンの高等学校での実験にちなんで名づけられました。各教科のカリキュラムを月単位の課題（アサイメント）に分け、生徒は教師と契約を結んで、自分で学習の計画を立てて進めます。ただし、一つの課題を終えてから次に進むという責任を負います。\n\n教科ごとに設けられた教室「ラボラトリー（実験室）」が学習の中心で、生徒は自由に出入りして教師の助言を受けながら課題に取り組みます。また、生徒の社会的な共同体としての「ハウス」も構成要素に挙げられています。パーカーストは、原理として自由（フリーダム）を第一に、協同（コオペレーション）を第二に挙げ、第三の要素としてアサイメントを位置づけました。自分の進度に合わせて学ぶ一方で、学習の報告を教師に直接行うことで、学習への責任を生徒自身に持たせる工夫です。\n\n日本では大正自由教育の時期に紹介され、沢柳政太郎が創設した成城小学校がその受容の中心の一つとなりました。アメリカやイギリスなどで一時広まりましたが、あまりに個人主義的であるとの批判を受けて衰退しました。近年は2019年に開校したドルトン東京学園のように、アサイメント、ラボラトリー、ハウスを柱とする学校も現れています。",
