      "学習内容の習熟の程度に応じて学習集団を分け、補充的・発展的な学習などを行う指導形態。「個に応じた指導」の一つ。",
    body: "習熟度別指導は、児童生徒の学習内容の習熟の程度に応じて学習集団を編成し、それぞれの集団に適した内容や進度で指導する形態です。算数・数学や英語などで多く行われています。たとえば、基礎の定着を図る補充的な学習を行うグループと、より進んだ内容に取り組む発展的な学習を行うグループに分けて授業を行います。日本では、平成10年の教育課程審議会答申が、理解や習熟の程度に応じて弾力的に学習集団を編成する「個に応じた指導」を提言しました。\n\nその後、平成15年10月の中央教育審議会答申を踏まえ、同年12月26日に学習指導要領の一部が改正され、「個に応じた指導」の一層の充実が図られました。答申に添付された資料によれば、平成15年度の計画では、小・中学校とも約7割の学校が必修教科で「学習内容の習熟の程度に応じた指導」を実施しており、補充的な学習に約7割、発展的な学習に約5割が取り組むとされていました。\n\n効果については、実践報告では意欲や達成感の向上が報告される一方、自治体による検証では、指導形態による学力の伸びに単純な優劣は示されていません。コースの分け方や固定化への懸念、担当教員間の打ち合わせ時間の確保、教材開発といった課題も指摘されています。そのため、少人数指導やティーム・ティーチングと組み合わせ、子どもの実態に応じて柔軟に運用することが重要とされています。",
    relatedSlugs: ["shoninzu-shido", "kobetsu-saiteki", "mastery-learning", "team-teaching"],
