    summary:
      "一つの学級をさらに少人数のグループに分けたり、複数教員で教えたりして行う授業形態。教職員配置改善計画の加配で広がった。",
    body: "少人数指導は、学級の児童生徒をいくつかの小集団に分けて、教員が少人数で指導する授業形態です。算数・数学や英語、国語などで、学習内容の習熟の程度に応じて分ける場合もあれば、学習内容や課題別、あるいは単に人数を減らすために分ける場合もあります。ティーム・ティーチング（TT）の実施と並んで、「個に応じた指導」を実現する手段として位置づけられてきました。\n\n制度面では、公立義務教育諸学校の教職員配置改善計画によって支えられています。第6次計画でTT指導のための加配が始まり、2001〜2005年度の第7次計画で、少人数指導のための加配が導入されたとされています。また、第7次計画の実施を通じて、国の標準は40人のまま、自治体の判断で国の基準より少人数の学級編制を行うことが可能となりました。少人数指導は、教育行政による予算措置や人員の加配によって成り立つ学習指導の方法だといえます。\n\n実践報告では、少人数指導と習熟度別指導を組み合わせ、担任と少人数担当の役割を共通理解するための年間指導計画を作る取り組みなどが報告されています。一方で、担当教員間の打ち合わせの時間の確保、教材開発、学校全体の運営構想などが課題とされます。学級そのものの人数を減らす少人数学級とは区別して理解する必要があります。",
