    slug: "cornell-note-taking",
    title: "コーネル式ノートテイキング",
    reading: "こーねるしきのーとていきんぐ",
    kana: "こ",
    categories: ["methods"],
    summary:
      "ページを手がかり欄・記録欄・要約欄に分けて講義や授業の内容を記録し、復習と自己テストにつなげるノート法。",
    body: "コーネル式ノートテイキングは、1950年代にコーネル大学のウォルター・ポーク（W. Pauk）が考案したとされるノートの取り方です。著書『How to Study in College』で紹介されて広まりました。ページを三つの領域に分け、左側の細い欄を「キュー（手がかり）欄」、右側の広い欄を講義中の詳細な記録欄、下部を要約欄とします。\n\n使い方の基本は、次の流れです。まず、授業や講義の間は右側の記録欄にメモを取ります。授業後にそれを見直して、左側のキュー欄に質問やキーワードを書き込みます。さらに、下部の要約欄に、そのページの要点を短くまとめます。復習の際には記録欄を隠してキュー欄だけを見ながら、内容を声に出して答える自己テストを行います。欄の寸法などの細部は資料によって異なります。\n\nこの方法は、単に書き写すのではなく、整理し、要約し、思い出す活動をノートに組み込むところに特徴があります。思い出す練習が記憶の定着を助けるという検索練習（テスト効果）や、自分の理解を点検するメタ認知の考え方とも整合します。高校や大学の講義での活用のほか、小中学校でもノート指導の一つとして取り入れられています。",
    relatedSlugs: ["retrieval-practice", "metacognition", "graphic-organizer", "bansho"],
    isCanonical: true,
    tags: ["ノート指導", "学習方略", "復習"],
