    body: "言語活動の充実は、平成20年1月17日の中央教育審議会答申で、教育内容に関する改善事項の第一に挙げられ、各教科等を貫く改善の視点とされた方針です。それを受けて平成20年に改訂された学習指導要領では、国語科だけでなく、各教科等で言語活動を位置づけた学習が重視されました。背景の一つに、PISA調査などで課題とされた思考力・判断力・表現力の育成がありました。\n\n答申では、言語活動の類型として、体験から感じたことを表現する活動、事実を正確に理解し伝達する活動、概念や法則などを解釈し説明・活用する活動などが示されました。国語科は言語力育成の基盤となる教科であることから、学習指導要領に言語活動例が充実して示されました。一方、社会・算数・理科など他の教科でも、記録、要約、説明、論述、討論などを通じて、考えを表現し合う学習が展開されました。\n\n実践上は、現場が「何か新しい言語の指導を加えなければならない」と受け止め、目的の共有が不十分なまま授業研究が進んだ例があるとの指摘もあります。言語活動は活動そのものが目的ではなく、教科の内容の理解を深め、思考を整理するための手段であることを押さえることが重要です。この方針は、その後の「主体的・対話的で深い学び」の考え方へもつながっています。",
