    body: "日本の学校教育において標準的な授業展開として定着している、1単位時間を3つの明確な局面に区分する構成法である。ヘルバルト派の教授段階論などを起源とし、学習者の動機づけから思考の深化、成果の定着までを論理的に組織する枠組みとして発展した。\n\n導入では前時の復習や問題の提示を通じて本時の課題をつかませる。展開では個人思考や小集団での話合い、全体での比較検討を通じて課題の探究と解決を進める。終末では分かったことを整理してまとめを行い、自己の学びを振り返る活動で締めくくる。\n\nこの3段階の枠組みは、児童生徒にとって見通しを持ちやすく、教員にとっても授業計画を論理的に構築しやすい利点を持つ。現在でも探究型学習や協働的な学びを取り入れる際の安定した授業デザインの骨格として活用されている。",
