    body: "プロンプトとフェイディングは、応用行動分析学に基礎を置く教授技法である。目標行動を自力で遂行できない学習者に対し、初期段階で適切な手がかり（プロンプト）を与えて成功体験を保証し、習熟度の上昇に伴って手引きを徐々に弱めて消去（フェイディング）することで自立を促す。\n\n授業では、身体的誘導や身振り、視覚的ヒント、言語的助言などのプロンプトを状況に応じて提示する。学習者が課題を反復する過程で、文字のなぞり書きの補助線を薄くする、助言の言葉を減らすなど支援を段階的に削減し、最終的には外的援助なしで正答や適切な行動ができるように導く。\n\n学習者の誤答や過度な依存を防ぎつつ、自律的な遂行能力を確実に育成できる。認知発達における足場かけ（スキャフォールディング）とも密接に関連し、特別支援教育のみならず、体育の実技指導や教科の記述指導など幅広い教育場面で応用されている。",
