    body: "オヴィド・デクロリーの興味の中心理論は、ベルギーの医師・心理学者デクロリーが障害児教育の実践を経て一般学校改革へと発展させた新教育理論である。従来の細分化された教科指導を廃し、「生活のための、生活による学校」という標語のもと、子どもの全体的認識（大局的知覚）に即した総合学習を提唱した。\n\n教育内容を人間の根本欲求（食物、防寒・住居、危険防御、労働と休息）から導き出された「興味の中心」に統合する。学習活動は、実物に直接触れて五感で調べる「観察」、時間的・空間的な広がりや因果関係を思考する「連合」、言語や工作・図画で表す「表現」の三段階を循環して構成される。\n\n分断された知識の受動的暗記を克服し、子どもの生活実感と自然・社会環境を有機的に結合させる教育効果をもたらした。近代ヨーロッパの新教育運動を力強く推進しただけでなく、現代の合科学習や生活科、総合的な学習のカリキュラム設計に多大な思想的影響を与えている。",
