    body: "ポートフォリオ面談と自己省察指導は、真正の評価（オーセンティック・アセスメント）論に基づき、客観テストでは測定できない思考力や学習プロセスの質を評価・育成する対話型指導法である。学習の成果物を長期的に収集・選抜・保存したポートフォリオを活用し、学習者の内省を深めることを中核とする。\n\n面談に先立ち、児童生徒は自己の蓄積物の中から成長を証明する作品を選び、自己評価シートを記入する。面談では教員と一対一で向き合い、なぜその作品を選んだのか、以前と比べて何ができるようになったのかを語る。教員は批判や指示を避け、受容的な問いかけによって学習者自身の言語化を促す。\n\n数値化された点数競争から解放され、自己の変容を肯定的に認識することで学習への当事者意識が芽生える。次の学習に向けた具体的な目標設定や自己調整学習の構えが培われ、高次思考力の育成と指導と評価の一体化を具現化する有力な手法である。",
