    body: "ルーブリックを活用した自己評価・相互評価は、パフォーマンス評価論および形成的評価の考え方に立脚した学習支援法である。評価基準を教員だけの秘密にせず、学習者と事前に共有することで、質の高い学習成果の構造を理解させ、自律的な修正や練り直しを促す目的で導入される。\n\n授業では、レポート作成や発表活動の前に到達水準を示したルーブリックを配布・解説する。学習者は作業途中で基準と照らし合わせて自己点検を行い、ペアやグループで互いの成果物を評価し合う。単なる点数付けではなく、「どの記述語に該当するか」「どう直せば上の段階に行けるか」を具体的に助言し合う。\n\n評価基準が内面化されることで、他者からの指摘を建設的に受け止め、自己の作品を主体的に修正するメタ認知能力が高まる。教員による採点の客観性が担保されるだけでなく、学習者を評価の受動的対象から能動的な吟味者へと変革する協同学習の基盤となる。",
