    body: "ＧＲＡＳＰＳモデルは、ウィギンズとマクタイが提唱した「理解をもたらすカリキュラム設計（逆向き設計）」において、真正の評価課題を作成するために開発された枠組みである。知識の断片的な再生を求める従来のペーパーテストを乗り越え、実社会で生きて働く本質的理解を測る課題設計の標準として考案された。\n\n課題設計は六つの頭文字（目標、役割、対象者、状況、成果物、評価基準）に基づいて行われる。例えば「観光局の広報官として（役割）、外国人旅行者に向け（対象者）、地域の歴史遺産の魅力を紹介するパンフレットを制作せよ（成果物）」といったように、学習者を具体的な社会的文脈に位置づけて思考を促す。\n\n架空の演習ではなく本物の目的や相手を意識することで、学習者の内発的動機づけと当事者意識が劇的に高まる。単元で学んだ知識を統合・応用する実践的活用力が試され、高校の探究学習や総合的な学習における質の高い課題設定手法として極めて重宝されている。",
