    body: "チャンク・リーディングとスラッシュ指導法とは、英文を意味のまとまり（チャンク）ごとに区切り、英語の語順のまま前から迅速に内容を把握させる指導法である。日本語の語順に合わせて後ろから訳し戻す「返り読み」を是正し、英語を英語の語順で理解する直読直解の処理能力を高めるために開発された。\n\n指導では、文の主部や述語、修飾節や前置詞句などの意味的な切れ目に区切り線（スラッシュ）を書き込ませる活動から導入する。学習者は区切られた単位ごとに音声と結びつけて意味を捉え、音読練習を反復する。習熟に応じて区切る間隔を徐々に広げ、最終的には区切り線がなくても大きな意味のかたまりで理解できるよう促す。\n\nこの指導により、英文を読む速度が劇的に向上するとともに、リスニングやスピーキングにおける文頭からの素早い理解力も同時に鍛えられる。膨大な英語情報を的確に処理することが求められる現代の外国語教育において、基礎的運用力を高める指導法である。",
