    body: "シャドーイングとリピーティング英語指導とは、流れてくる音声を模倣して即座に発話する訓練を通じて、音声知覚の自動化と発話の流ちょう性を高める指導法である。通訳訓練法から発展し、認知心理学や第二言語習得論の知見を背景に、学校教育の現場へ広く導入されてきた。\n\n授業では、まず意味を理解した英文を用い、一文や句の区切りを聞き終えた直後に繰り返すリピーティングから始める。続いて、音声を聞きながら影のようにわずかに遅れて声に出すシャドーイングへと移行する。リズムや強弱、脱落などの音声変化に集中させ、反復的な練習を個人やペアで実施する。\n\n音声知覚が自動化されることで、学習者の作業記憶（ワーキングメモリ）の負担が軽減され、内容理解や自己表現により多くの認知的資源を配分できるようになる。英語の4技能を統合的に育成する授業改善において、音声面の基盤を固める指導法として重要である。",
