    body: "フォニックス指導法とは、英語の文字（つづり）と音声との間にある規則的な対応関係を体系的に指導し、読み書きの基礎を築く教授法である。英語圏における子どもの文字習得法として発展し、日本の小・中学校の外国語教育においても、自立的な学習を支える基礎技術として重視されている。\n\n指導では、アルファベットの文字名称と、その文字が単語の中で持つ実際の音の違いを認識させることから始める。子音と母音の結合規則や二重母音の法則を平易な単語を用いて段階的に教え、手拍子や身体動作、文字カードの操作を交えて楽しく練習する。未知の単語を見ても自力で音読できるよう訓練する。\n\nこの規則性を修得することで、単語を丸暗記する負担が軽減され、学習者は自ら本を読んだり書いたりする自己効力感を高めることができる。小学校英語から中学校英語への円滑な接続を図り、生涯にわたる英語学習の土台を築く指導法として高い教育効果を持つ。",
