    body: "道徳科における心の数直線とは、黒板やワークシート上に一本の直線を提示し、登場人物や自己の心情の度合いを位置づけて可視化する指導手法である。思考の外化を促す概念図の理論を基盤とし、捉えにくい心の揺らぎを構造的に整理させる工夫として開発された。\n\n授業では、両極に対立する価値観や心情（例えば「注意する」と「見過ごす」など）を設定した直線を提示する。児童生徒は自分の判断や登場人物の心の状態を示す位置に名札や印を置く。なぜその位置を選んだのかを根拠とともに説明し合い、物語の展開や仲間の意見を聞いた後に位置を移動させることで心情の変化を実感させる。\n\n白黒の二者択一に陥りがちな道徳的思考を柔軟にし、複雑な心理の移り変わりや葛藤の深さを視覚的に把握できる効果がある。他者との相違が一目で把握できるため、活発な意見交流が自然と生み出され、多面的・多角的な自己省察を促す優れた授業改善手法である。",
