    body: "話合い活動における司会団育成指導とは、学級会等の話合いにおいて児童生徒自身が司会や記録などの役割を担い、民主的な議事進行を行えるよう教師が意図的に支援・育成する指導法である。学習者の自己決定と集団的自治を重んじる特別活動論に立脚している。\n\n指導の手順として、まずは司会団の事前打合せを設け、話合いのねらいや予想される意見の広がりを確認させる。本番では、司会者が発言を促し、黒板記録者が意見を分類して可視化し、時間配分を意識しながら議事を進められるよう、教師は必要最小限の助言にとどめる。終了後には司会団の進行ぶりを丁寧に振り返り、改善点を共有する。\n\n司会団を育成することで、教師主導の一方的な授業から児童生徒主体の自治的な対話空間へと教室が転換される。進行役を交代で経験することにより、学級全員に助け合いと傾聴の意識が浸透し、協働的な問題解決を支える市民的リーダーシップが育まれる。",
