    body: "学級会における議題設定と合意形成プロセスとは、集団生活の課題や児童生徒の願いから適切な検討課題を見出し、対話を通じて全員が納得できる解決策を共創していく指導論である。形式的な多数決による勝敗の決定を排し、熟議による民主的な合意形成を重視する。\n\nプロセスの第一段階として、生活の中で生じた問題意識や願いを事前に集約し、学級全員で取り組む価値のある議題を設定する。話合いの段階では、各提案の理由を比較検討し、対立する意見の背景にある共通の願いを掘り起こす。条件付きの賛成や修正案を練り上げることで、全員の納得解を導き出す。\n\nこの指導により、安易な数の力で少数意見を排除する傾向を克服し、他者への尊重と妥協点を見出す高度な対人関係能力が育成される。自己の意見が集団の決定に反映される喜びを実感させることで、民主社会を主体的に生きる主権者意識の基盤が形成される。",
