    body: "集団宿泊学習・自然体験活動の事前事後指導とは、学校を離れた宿泊体験や自然体験を単なる一過性の行事に終わらせず、事前の周到な計画と事後の丁寧な省察を有機的に連動させる指導法である。体験を通じて得た学びを確固たる人格的成長へと昇華させる体験学習理論に基づいている。\n\n事前指導では、体験の教育目標を共有し、児童生徒自らに係活動や生活ルールの立案、現地の自然環境や歴史の調査を委ねる。活動本番を経て、事後指導では個人の記録や写真を用いて活動を振り返り、協働の中で発見した自己の長所や課題を言語化する。最後に成果を報告書や発表会として発信する。\n\n一連の指導過程を経験することで、非日常の体験が日常の学校生活や学習意欲の向上へと結びつく。自然の美しさや厳しさに触れる感性の育成とともに、自己管理能力や仲間と助け合う協調性が培われ、現代の豊かな人間形成に不可欠な体験教育の骨格となっている。",
