    body: "職場体験学習・インターンシップ事前事後指導とは、事業所等での就業体験を中核とし、事前のマナー習得や職業理解、事後の省察と進路設計を一貫して支援するキャリア教育の指導法である。実社会の労働現場に触れる体験を通じて、職業観や勤労観を育成する目的で体系化された。\n\n事前指導では、希望職種の調査や自己分析を行い、電話での依頼連絡や挨拶、礼儀作法などの社会人マナーを練習する。体験本番では実際の職務に従事し、事後指導では事業所への礼状執筆を行うとともに、体験で得た気づきや自己の適性を記録して報告会で共有する。\n\nこの一連の指導により、働くことの喜びや厳しさを肌で感じ、将来の自立に向けて学ぶ目的意識が明確になる。学校での学習と実社会のつながりを実感させ、主体的に自己の進路を切り拓くキャリア形成の基盤を養う極めて重要な教育活動である。",
