    body: "キャリア・パスポートを活用した対話指導は、児童生徒が自らの学習状況やキャリア形成を見通し、振り返るために記録を蓄積・活用する教育手法である。中央教育審議会の答申を受け、小・中・高等学校を通じたキャリア教育の円滑な接続と、自己調整学習能力の育成を目指して導入された背景を持つ。\n\n授業では、各学期や単元の節目に目標設定や活動の振り返りをワークシートに記述させる。教師は単に提出物として点検するだけでなく、記述内容を足がかりに一人ひとりと個別面談や対話的なやり取りを行う。学習者が自らの努力や他者との関わりを再認識できるよう、適切な助言や励ましを与える。\n\n長期間にわたる記録の蓄積により、児童生徒は自己の成長や変容を実感し、将来の進路や生き方についての主体的な意思決定力を培う。新学習指導要領が重視する特別活動や総合的な探究の時間と有機的に結びつくことで、資質・能力の継続的な把握と個別最適な学びの実現に貢献する。",
