    body: "ピア・レスポンスは、学習者が作成途中の文章を持ち寄り、仲間同士で読み合って感想や改善策を伝え合う協働的な文章指導手法である。認知心理学や構成主義の知見に基づき、文章作成を単なる個人的な技能ではなく、読者との対話を通じた意味生成のプロセスとして捉える視点から普及した。\n\n指導手順としては、まず教師が相互交流の観点や助言の作法を示した上で、学習者がペアや小集団を組む。各自が書いた下書きを朗読したり交換したりし、読者として「良かった点」や「さらに疑問に思った点」を伝え合う。書き手は仲間の反応を参考にしながら、表現の修正や構成の再検討に取り組む。\n\n想定される読者意識が明確になることで、独りよがりな表現を脱し、客観的で説得力のある文章表現力が養われる。また、他者の多様な発想や構成力に触れることで自己のメタ認知が高まり、現代の国語科や総合的な探究学習における論述指導の重要な実践として位置づけられている。",
