    body: "ライティング・ワークショップは、教室を作家の仕事場に見立て、学習者が主体的な書き手として文章創作に没頭する協同的な指導法である。アメリカの教育学者アトウェルらが提唱したプロセス・アプローチに端を発し、画一的な課題作文を脱却して個人の内発的動機に基づく表現力を培う理論的背景を持つ。\n\n授業は、教師が文章表現の技術や着眼点を実演する短い指導（ミニレッスン）から始まる。その後、学習者は各自で題材選び、構想メモ、下書き、相互検討、清書という創作過程を自由な進度で進める。教師は教室内を巡回しながら個別相談を行い、一人ひとりの進度やつまずきに応じた助言を与える。\n\n書くことへの自己効力感や表現への愛着が深まり、自らの思いを論理的かつ豊かに伝える主体性が育まれる。単なる試験対策を超え、探究の成果発信や社会に向けた提言など、現代の主体的・対話的で深い学びを実現する先進的な国語教育モデルとして注目されている。",
