    body: "リーディング・ワークショップは、画一的な一斉読解を脱し、学習者一人ひとりが自立した読者として読書に没頭する時間を保障する教授法である。アメリカの教育改革の中で体系化され、読解を個人の能動的な意味構成活動と捉える読書教育の理念に基づいている。\n\n授業構成は、教師が読書方略や思考法を例示する短い指導から開始される。続いて学習者は、教室内の学級文庫や図書館から自ら選んだ本を一定時間、集中して黙読する。この間に教師は個別面談を実施し、読書の進み具合や理解の深まりを対話で確認しながら、次の思考を促す問いかけを行う。\n\n強制的な読書感想文や受動的な読解とは異なり、読書の喜びそのものを実感しながら自律的な情報収集力や批判的思考力が養われる。多様な本に触れる経験は探究学習の基盤となる読解力を底上げし、個別最適な学びと協働的な語り合いを接続する手法として重視されている。",
