    body: "読書へのアニマシオンは、スペインの児童文学者モンセラット・サントスが開発した体系的な読書推進指導法である。「アニマシオン」とは魂を吹き込み活性化させることを意味し、子どもを受動的な読書から解放し、本の世界に能動的に参加させることを目指して創始された。\n\n指導者は「アニマドール」として振る舞い、読解を促す多様な作戦（ゲーム）を展開する。例えば、物語の結末を隠して展開を予想させたり、登場人物の手紙を創作させたり、誤ったあらすじの中から正解を探し出させたりする活動を行う。子どもたちは小集団で協力しながら本の内容を多角的に検証する。\n\n単なる活字の追走にとどまらず、テキストを批判的かつ構造的に読み解く確かな学力と言語運用能力が身につく。読書を楽しい協働体験へと転換させることで、読書離れを防ぎ、現代の学校図書館教育や国語科の授業改善において極めて高い教育的価値を発揮している。",
