    body: "ビブリオバトルは、京都大学で考案された知的書評ゲームであり、今日では小・中・高等学校の授業や特別活動に広く導入されている。「本を通して人を知る、人を通して本を知る」を理念とし、競争と協働を融合させた対話型コミュニケーション手法として定着した。\n\n実践では、学習者が各自で選んだ推薦書を手に持ち、レジュメ等を用いずに制限時間（通常3〜5分）で本の魅力を語る。発表後は全員で数分間の質疑応答を行い、内容を深める。全員の発表が終わった後、「どの本が一番読みたくなったか」を基準に全員が1票を投じ、最多票の「チャンプ本」を決定する。\n\n限られた時間で要点を論理的に伝えるプレゼンテーション能力と、他者の発言を傾聴して的確に質問する対話力が同時に伸長する。また、未知の書籍や多様な価値観に出会う契機となり、主体的・対話的で深い学びを具現化する言語活動として高く評価されている。",
