    body: "ニュースポーツを活用した共生体育指導は、伝統的な近代スポーツの過度な競争性や身体能力偏重を見直し、誰もが生涯にわたって親しめる運動環境を提供する教授法である。共生社会の形成やインクルーシブ教育の要請を背景に、運動の多様性と楽しさを保障する体育実践として確立された。\n\n授業では、ボッチャやキンボールなど、初心者でも取り組みやすく身体接触の少ない競技種目を導入する。学習者はチーム内で役割を分担し、個々の体力や障害の有無に応じた特別ルールの改変や作戦の立案を話し合う。教師は一人ひとりの貢献を認め、相互承認の雰囲気を醸成する。\n\n運動への苦手意識や疎外感を軽減し、自己効力感と仲間との連帯感を育む効果がある。多様な他者と協力してルールを調整・合意形成するプロセスは、単なる体力向上にとどまらず、共生社会に必要な協調性や共感性を養う道徳的・市民的学習の場として極めて有意義である。",
