    body: "協働的課題解決能力（CPS）の育成法は、21世紀型スキルや国際的な学力調査において重要視される資質・能力を育む指導理論である。個人の認知能力だけでなく、他者との円滑な対話、役割分担、視点の調整を通じて共同の理解を築き上げる社会的相互作用を中核に置いている。\n\n授業設計では、一人の力では解決困難な複雑な問いやジレンマ課題を設定する。学習者はチームを組み、各自が異なる情報や役割（情報収集、進行、記録、調整など）を受け持つ。進捗状況を共有しながら多角的な視点で意見を交わし、合意を形成しながら最適な解決策を共同で導出する。\n\n自己の考えを論理的に説明しつつ、他者の異論を受け入れながら新たな発想を創出する高度な協調的思考力が培われる。現代社会における予測困難な地域課題や環境問題の解決に直結し、探究学習やプロジェクト型学習を成功に導く基盤的スキルとして不可欠である。",
    relatedSlugs: ["active-learning", "pbl", "kyodo-gakushu", "tankyu-gakushu"],
    isCanonical: true,
    tags: ["協働学習", "課題解決", "21世紀型スキル", "合意形成"],
