    body: "チーム基盤型学習（TBL）は、アメリカのミケルセンが創始した体系的な協働学習フレームワークである。医学教育などの専門職養成を中心に発展し、受動的な講義形式を克服して、学習者が主体的に知識を応用・実践する能動的な授業形態として世界中に広がった。\n\n授業プロセスは明快に構造化されている。まず学習者は教材を予習した上で個人テストを受け、続いて同じテストに固定された小グループで挑戦し議論を通じて正解を導く。その後、教師による要点解説を経て、チームごとに現実的で複雑な応用課題の解決と全体討議に取り組む。\n\n個人の事前準備への責任感が高まるとともに、仲間への説明や反論を通じて概念の深い理解と定着が達成される。また、恒常的なチーム活動を通じてチームワークや対人関係調整能力が自然に磨かれ、高等教育や高校の探究学習における強力な授業改善手法となる。",
