    body: "PBLチュートリアル方式は、カナダのマックマスター大学医学部で創始された学習者中心の教育手法である。知識を系統的に教授されてから演習する従来法と逆転させ、未整理な現実の課題シナリオに直面させることで、自律的な学習動機と生涯学習力を引き出す構成主義的背景を持つ。\n\n学習は数名の小グループと支援者（チューター）で進められる。提示された事例から問題点を抽出し、仮説を立てた後、解決に不足している知識を「学習課題」として設定する。各自が自己主導的に資料調査や自習を行い、再び集まって得た知見を持ち寄り、多角的に事例を再分析する。\n\n知識の単なる暗記にとどまらず、実践現場で活用可能な生きた概念として統合される。また、自ら学びの道筋を立てる自己調整力と批判的思考力が飛躍的に向上し、現代の中等・高等教育における課題解決型探究や総合学習の中核的手法として高く評価されている。",
