    body: "デジタル・ストーリーテリング（DST）は、アメリカのランバートらが市民運動の中で提唱したメディア表現の手法である。個人の内面的な感情や記憶をデジタルの力を借りて形にし、共有し合うことで、自己開示と他者理解を促進する構成主義的な教育実践として発展した。\n\n学習過程は脚本作りから始まる。学習者は自らの印象的な経験を文章にまとめ、小集団での対話を通じて内容を磨き上げる。その後、写真や絵、自らの語りの音声、音楽をデジタル機器で編集し、短編の映像作品を完成させる。最後に学級全体で上映会を開き、相互に鑑賞と感想を共有する。\n\n文字表現と視聴覚メディアを統合する高度な表現力とメディアリテラシーが育成される。同時に、仲間の知られざる経験や心情に共感的に耳を傾けることで、温かな学級集団づくりや自己肯定感の向上に大きく寄与し、国語科や総合的な探究の時間で実践されている。",
