    body: "PREP法を活用した指導法は、ビジネスや学術報告で汎用される伝達の型を学校教育の言語活動に応用した教授技法である。認知心理学における情報処理理論に基づき、聞き手が理解しやすい順序で情報を提示することで、説得力のあるコミュニケーション力を育む意図を持つ。\n\n指導手順では、まず主張の要点（結論）を一言で述べ、次にその判断に至った客観的な理由を明示する。続けて理由を裏付ける具体的な事実や実例、データを提示し、最後に結論を再確認して締めくくる構成を教える。学習者はこの骨組みに沿って思考ツールや原稿を整理し、発表練習を行う。\n\n話が発散したり主旨が不明瞭になったりするのを防ぎ、誰に対しても要点を明確に伝える論理的思考力が定着する。探究学習の成果発表、国語科の意見文作成、特別活動での合意形成など、あらゆる教科横断的場面で活用できる基礎的言語スキルとして極めて有効である。",
