    body: "QFT法（問い作りの技術）は、アメリカのロススタインとサンタナが開発した、学習者が自律的に問いを生成するための指導技法である。教師の発問に答えるだけの受動的な授業構造を転換し、知的好奇心と自律的探究心を喚起する理論的根拠に基づいている。\n\n手順は厳密に規定されている。教師が「問いの焦点」となる刺激的な言葉や画像を提示すると、学習者は「批判しない」「出た通りに書く」「言明を問いに変える」という規律のもとで問いを乱出する。次に問いを「閉じた問い」と「開いた問い」に分類・変換し、最後に探究に最も適した問いを優先順位づけて選出する。\n\n問いを生み出すプロセスそのものを客観視することで、学習者のメタ認知能力と知的主体性が飛躍的に高まる。総合的な探究の時間や教科学習の導入段階で用いることで、課題設定の質を根本から改善し、深い探究の推進力となる。",
