    body: "シックス・シンキング・ハッツは、マルタの心理学者エドワード・デボノが創案した多面的思考法である。人間が思考する際、論理と感情、批判と楽観が混ざり合って議論が紛糾しやすいことに着目し、思考の方向性を意図的に分離・同期させる技法として考案された。\n\n授業では、白（客観的事実）、赤（感情・直感）、黒（慎重・批判）、黄（肯定・利益）、緑（創造・新提案）、青（全体管理）の役割を象徴する帽子を用いる。参加者全員が同時に同じ色の帽子を着用した想定で意見を出し合い、順番に視点を切り替えながら一つの課題を多角的に検証していく。\n\n感情的な衝突や自己主張の対立を防ぎ、学習者全員が心理的安全性を保ちながら多面的な視点から物事を考察できる。探究学習における複雑な社会課題の分析や、学級活動での合意形成において、公平で建設的な集団思考を実現する強力なツールとなる。",
