    body: "SCAMPER法は、オズボーンのブレインストーミング手法を発展させ、エバーレが整理した体系的アイデア発想技法である。創造性を特別な天才の資質ではなく、既存の知識を系統的な視点操作によって変容させる認知技能と捉える教育的理念に基づいている。\n\n指導では、既存の事物や提案に対し、代用（他で代えられないか）、結合（組み合わせられないか）、応用（他分野の知見を使えないか）、修正・拡大（大きくできないか）、転用（他の使い道はないか）、削除（省けないか）、再編成（順序を逆にできないか）の7つの問いを順次適用させ、柔軟に発想を広げさせる。\n\n発想に行き詰まった学習者に対して具体的で実践的な思考の足場かけを提供し、固定観念を打破する柔軟な創造性を培う。総合的な探究の時間、STEAM教育、技術・図画工作科における設計や新商品開発などの探究的活動に広く応用されている。",
