    body: "シネクティクス法は、アメリカのゴードンが開発した類比（アナロジー）に基づく創造的発想法である。異なる要素を結びつけることを意味するギリシャ語に由来し、論理的思考の枠組みをあえて外し、比ゆや感情移入を活用して潜在意識から革新的な着想を引き出す心理学的背景を持つ。\n\n活動では「見慣れたものを異質なものに見立てる」「未知のものを身近なものに例える」訓練を行う。自然界の仕組みに例える「直接類比」、自分が対象物になりきる「擬人類比」、矛盾する語句を組み合わせる「象徴的類比」などを段階的に用いて、課題への固定的な見方を揺さぶり、独創的な解決の糸口を探る。\n\n直感と論理を架橋し、常識的な枠組みを超えた高度な発想力と概念統合力を育む。理科教育における科学的モデルの構築、芸術的表現の創出、さらには高校の探究学習における独創的な課題設定や新提案の立案において先駆的な効果を発揮する。",
