    body: "SQ3R読解法は、教育心理学者フランシス・ロビンソンが第二次世界大戦中に考案した体系的な学習・読解技術である。認知心理学におけるスキーマ理論に根ざし、漫然とした受動的通読を排して、目的意識を持った能動的な情報処理を促す方略として広く普及した。\n\n学習者は5段階を踏んで読書を進める。まず見出しや図表を概観する「調査」、見出しを問いの形に変換する「質問」、その問いの答えを探しながら読む「精読」、顔を上げて要点を自分の言葉で確認する「暗唱」、最後に全体を再点検する「復習」を一連の学習サイクルとして実行する。\n\nテキストに対する事前知識が活性化され、重要概念の論理的関係を把握する深い理解と記憶の長期保持が実現する。自立した自習習慣の確立や、探究学習における専門文献の読解指導において、学習の自己調整力を育む基本技法として今日でも高く評価されている。",
