    body: "要約と構造化を促すノート指導法は、講義や資料の情報を単に書き写す受動的記録から、自らの認知構造に組み込む能動的思考ツールへとノートを変革する指導法である。コーネル大学で開発されたノート術をはじめ、情報の詳細化と記憶定着を促す認知方略に基づいている。\n\n指導では、ノートの紙面を「記録欄」「要約・重要語欄」「振り返り・問い欄」などに区画分けさせる。授業中には重要語や因果関係を矢印・記号を用いて構造的に記述させ、単元の終わりには自らの言葉で要約文や疑問点を記述させる。定期的に相互閲覧を行い、表現の工夫を共有する。\n\n情報の取捨選択と再構築を行う中でメタ認知と思考の構造化能力が自然と鍛えられる。自分だけの学びの履歴として蓄積されるため、テスト前の効果的な復習だけでなく、探究活動における思考の整理や自己調整学習の強力な土台となる。",
