    body: "授業リフレクションは、授業後の教師が自らの指導行動や児童生徒の学びの事実を省察し、教育実践を改善し続ける専門的成長の手法である。ショーンの「反省的実践家」の理論を基盤とし、指導技術の定型的な適用を超えて、複雑な教室現場で生きた実践知を紡ぎ出す営みとして位置づけられる。\n\n授業研究会などの場において、授業者と参観者は単なる評論や評価を避け、「ある場面で子どもがどう学んでいたか」「教師のどの言葉が学びを転換させたか」という事実に基づいて語り合う。授業者自身の葛藤や気付きを率直に共有し、次回への具体的な授業仮説を再構築する。\n\n教師が孤立した指導技術者から学び続ける省察者へと変容し、学校全体に協働的で心理的安全性の高い同僚性が育まれる。子ども主体の授業観への転換を促すとともに、校内研修や授業研究を形骸化から救う不可欠な教師教育サイクルとして確立されている。",
